 "use client";

import { useMemo, useState } from "react";

type Fee = {
  id: string;
  studentName: string;
  admissionNo: string;
  academicYear: string;
  amount: number;
  paidAmount: number;
  status: string;
  dueDate: string;
};

export default function FeeRecords({ fees }: { fees: Fee[] }) {
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("ALL");
  const [sortOrder, setSortOrder] = useState("ASC");

  const filteredFees = useMemo(() => {
    return fees
      .filter((fee) => {
        const text = `${fee.studentName} ${fee.admissionNo} ${fee.academicYear}`.toLowerCase();
        const matchesSearch = text.includes(search.toLowerCase());
        const matchesFilter =
          filter === "ALL" || fee.status.toUpperCase() === filter;

        return matchesSearch && matchesFilter;
      })
      .sort((a, b) => {
        const difference =
          new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();

        return sortOrder === "ASC" ? difference : -difference;
      });
  }, [fees, search, filter, sortOrder]);

  const totalAmount = fees.reduce((sum, fee) => sum + fee.amount, 0);
  const totalPaid = fees.reduce((sum, fee) => sum + fee.paidAmount, 0);
  const outstanding = totalAmount - totalPaid;

  const money = (value: number) =>
    `₹${value.toLocaleString("en-IN")}`;

  return (
    <div className="space-y-6">

      {/* Summary */}
      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">

        <div className="rounded-2xl bg-[#111827] p-6 text-white shadow">
          <p className="text-sm text-gray-300">Total Fees</p>
          <h2 className="mt-2 text-3xl font-bold">
            {money(totalAmount)}
          </h2>
        </div>

        <div className="rounded-2xl bg-emerald-600 p-6 text-white shadow">
          <p className="text-sm text-emerald-100">Total Collected</p>
          <h2 className="mt-2 text-3xl font-bold">
            {money(totalPaid)}
          </h2>
        </div>

        <div className="rounded-2xl bg-blue-600 p-6 text-white shadow">
          <p className="text-sm text-blue-100">Outstanding</p>
          <h2 className="mt-2 text-3xl font-bold">
            {money(outstanding)}
          </h2>
        </div>

      </div>

      {/* Records */}
      <div className="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm">

        <div className="mb-5 flex flex-col justify-between gap-4 md:flex-row md:items-center">
          <div>
            <h2 className="text-xl font-bold text-gray-900">
              Fee Records
            </h2>
            <p className="text-sm text-gray-500">
              Manage and review student fee payments.
            </p>
          </div>

          <input
            type="text"
            placeholder="Search student..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-blue-500"
          />
        </div>

        {/* Filters */}
        <div className="mb-5 flex flex-wrap gap-2">

          {["ALL", "PAID", "PENDING", "OVERDUE"].map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`rounded-lg px-4 py-2 text-sm font-semibold transition ${
                filter === status
                  ? "bg-blue-600 text-white"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              {status}
            </button>
          ))}

          <button
            onClick={() =>
              setSortOrder(sortOrder === "ASC" ? "DESC" : "ASC")
            }
            className="rounded-lg bg-emerald-50 px-4 py-2 text-sm font-semibold text-emerald-700"
          >
            Due Date: {sortOrder === "ASC" ? "Oldest" : "Newest"}
          </button>

        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">

            <thead className="bg-gray-50 text-xs uppercase text-gray-500">
              <tr>
                <th className="px-4 py-4">Student</th>
                <th className="px-4 py-4">Academic Year</th>
                <th className="px-4 py-4">Amount</th>
                <th className="px-4 py-4">Paid</th>
                <th className="px-4 py-4">Balance</th>
                <th className="px-4 py-4">Status</th>
                <th className="px-4 py-4">Due Date</th>
              </tr>
            </thead>

            <tbody className="divide-y divide-gray-100">

              {filteredFees.map((fee) => {
                const balance = fee.amount - fee.paidAmount;
                const status = fee.status.toUpperCase();

                return (
                  <tr key={fee.id} className="hover:bg-gray-50">

                    <td className="px-4 py-4">
                      <p className="font-semibold text-gray-900">
                        {fee.studentName}
                      </p>
                      <p className="text-xs text-gray-500">
                        {fee.admissionNo}
                      </p>
                    </td>

                    <td className="px-4 py-4 text-gray-600">
                      {fee.academicYear}
                    </td>

                    <td className="px-4 py-4 font-medium">
                      {money(fee.amount)}
                    </td>

                    <td className="px-4 py-4 font-semibold text-emerald-600">
                      {money(fee.paidAmount)}
                    </td>

                    <td className="px-4 py-4 font-semibold text-red-500">
                      {money(balance)}
                    </td>

                    <td className="px-4 py-4">
                      <span
                        className={`rounded-full px-3 py-1 text-xs font-bold ${
                          status === "PAID"
                            ? "bg-emerald-100 text-emerald-700"
                            : status === "OVERDUE"
                              ? "bg-red-100 text-red-700"
                              : "bg-amber-100 text-amber-700"
                        }`}
                      >
                        {status}
                      </span>
                    </td>

                    <td className="px-4 py-4 text-gray-600">
                      {new Date(fee.dueDate).toLocaleDateString("en-IN")}
                    </td>

                  </tr>
                );
              })}

              {filteredFees.length === 0 && (
                <tr>
                  <td colSpan={7} className="py-12 text-center text-gray-500">
                    No fee records found.
                  </td>
                </tr>
              )}

            </tbody>
          </table>
        </div>

        <div className="mt-4 text-sm text-gray-500">
          Showing {filteredFees.length} of {fees.length} records
        </div>

      </div>
    </div>
  );
}